// Slice 41: transport charges (phase-5-extended.md rule 37, R326-R328; contracts/slice-41.md §2.6,
// §2.7). The months are generated by the job body as the worker runs it (runMonth, daily);
// assignments, amounts, concessions, section changes and withdrawals go through the API on a
// moved school clock (SchoolClock overridden). The real AppModule and database.
import { NestExpressApplication } from '@nestjs/platform-express';
import { ErrorCode, newIdempotencyKey } from '@asms/shared';
import { SchoolClock } from '../../src/common/school-clock';
import { createTestApp } from '../core/app';
import { daily, db, karachi, runMonth } from '../fees/charges-support';
import { fixedClock } from '../payroll/support';
import { closeTestDb } from '../support/schools';
import { day } from '../support/students';
import { errorOf, fieldOf, transportHttp, type TransportWorld } from './support';

describe('slice 41: transport charges (e2e)', () => {
  let app: NestExpressApplication;
  const clock = fixedClock('2026-04-01');
  const h = transportHttp(() => app, clock);
  const { post } = h;

  beforeAll(async () => {
    app = await createTestApp({ overrides: [{ provide: SchoolClock, useValue: clock.value }] });
  });
  afterAll(async () => {
    await app.close();
    await closeTestDb();
  });

  const month = (w: TransportWorld, period: string, opts: { regenerateVoided?: boolean } = {}) =>
    runMonth(app, w.school, w.year, period, karachi(`${period}-02`), opts);
  /** [studentId, period, amount] of the school's transport charges, live ones. */
  const charged = async (w: TransportWorld) =>
    (await h.transportCharges(w)).filter((c) => c.status !== 'voided').map((c) => [c.studentId, c.period, c.amount]);

  it('R327: the cut-off, a mid-month end charged in full, a left enrolment not charged, once per student-period', async () => {
    const w = await h.world();
    const [stopA] = w.route.stops;
    const a = await h.child(w, 'Hamza Tariq');
    const b = await h.child(w, 'Hira Tariq');
    const c = await h.child(w, 'Zainab Khan');
    const d = await h.child(w, 'Bilal Shah');
    await h.assigned(w, a, '2026-04-01', { stopId: stopA?.id });
    // After the cut-off (the 15th): not charged April.
    await h.assigned(w, b, '2026-04-20');
    const cRide = await h.assigned(w, c, '2026-04-10');
    await h.assigned(w, d, '2026-04-01');

    await month(w, '2026-04');
    // Ended on 5 May: May is charged in full, June not at all.
    clock.state.today = '2026-05-05';
    await h.end(w, cRide.id, '2026-05-05').expect(200);
    // D's enrolment ends on 31 May (the assignment left live): the leaving month in full, then nothing.
    await db().enrolment.updateMany({
      where: { schoolId: w.school.id, id: d.enrolmentId },
      data: { status: 'left', endedOn: day('2026-05-31') },
    });
    await month(w, '2026-05');
    await month(w, '2026-06');
    expect(await charged(w)).toEqual([
      [a.studentId, '2026-04', 2000],
      [c.studentId, '2026-04', 2000],
      [d.studentId, '2026-04', 2000],
      [a.studentId, '2026-05', 2000],
      [b.studentId, '2026-05', 2000],
      [c.studentId, '2026-05', 2000],
      [d.studentId, '2026-05', 2000],
      [a.studentId, '2026-06', 2000],
      [b.studentId, '2026-06', 2000],
    ]);
    // Generated monthly rows under the Transport head, on the enrolment, labelled by month.
    const [first] = await h.transportCharges(w, a.studentId);
    expect(first).toMatchObject({
      kind: 'generated',
      headFrequency: 'monthly',
      enrolmentId: a.enrolmentId,
      grossAmount: 2000,
      concessionAmount: 0,
      description: 'Transport April 2026',
      status: 'open',
    });

    // The daily catch-up and a second run of the same month write nothing more.
    await daily(app, w.school, karachi('2026-06-20'));
    await month(w, '2026-06');
    expect(await charged(w)).toHaveLength(9);
    // The run's counts include the transport rows.
    const runs = await db().chargeRun.findMany({ where: { schoolId: w.school.id, period: '2026-04' } });
    expect(runs.map((r) => r.chargesInserted)).toEqual([4 + 3]);
  });

  it('R326: a section change in the month yields exactly one transport charge, on the enrolment of the 1st', async () => {
    const w = await h.world();
    const e = await h.child(w, 'Usman Ali');
    const ride = await h.assigned(w, e, '2026-04-01');
    await month(w, '2026-04');
    clock.state.today = '2026-05-11';
    const moved = await post(
      `/enrolments/${e.enrolmentId}/change-section`,
      { sectionId: w.section2.id.toString(), effectiveOn: '2026-05-11', reason: 'Moved to section B' },
      w.office,
    ).expect(200);
    const opened = BigInt((moved.body as { opened: { id: string } }).opened.id);
    await month(w, '2026-05');
    await daily(app, w.school, karachi('2026-05-20'));
    await month(w, '2026-06');
    const rows = await h.transportCharges(w, e.studentId);
    expect(rows.map((r) => [r.period, r.enrolmentId, r.amount])).toEqual([
      ['2026-04', e.enrolmentId, 2000],
      ['2026-05', e.enrolmentId, 2000],
      ['2026-06', opened, 2000],
    ]);
    // The assignment is keyed per student per year: the section change does not end it.
    const row = await db().transportAssignment.findFirstOrThrow({ where: { schoolId: w.school.id, id: BigInt(ride.id) } });
    expect([row.endedAt, row.enrolmentId]).toEqual([null, e.enrolmentId]);
  });

  it('R327: an amount change applies from the next period; a future amount may be voided before its month', async () => {
    const w = await h.world();
    const a = await h.child(w, 'Hamza Tariq');
    await h.assigned(w, a, '2026-04-01');
    clock.state.today = '2026-06-10';
    const now = await post(`/transport-routes/${w.route.id}/amounts`, { amount: 2500, effectivePeriod: '2026-06' }, w.office);
    expect([now.status, fieldOf(now)?.path, fieldOf(now)?.code]).toEqual([422, 'effectivePeriod', ErrorCode.TRANSPORT_AMOUNT_PERIOD_PAST]);
    await post(`/transport-routes/${w.route.id}/amounts`, { amount: 2500, effectivePeriod: '2026-07' }, w.office).expect(201);
    const taken = await post(`/transport-routes/${w.route.id}/amounts`, { amount: 2600, effectivePeriod: '2026-07' }, w.office);
    expect([taken.status, errorOf(taken).code]).toEqual([409, ErrorCode.TRANSPORT_AMOUNT_PERIOD_TAKEN]);
    // The database voids only a month not yet started on the real clock, so the mistake is a later one.
    const august = (await post(`/transport-routes/${w.route.id}/amounts`, { amount: 3000, effectivePeriod: '2027-01' }, w.office).expect(201))
      .body as { id: string; voidable: boolean };
    expect(august.voidable).toBe(true);
    await post(`/transport-route-amounts/${august.id}/void`, { reason: 'Typed the wrong amount' }, w.office).expect(200);
    const april = w.route.amounts[0]?.id ?? '';
    const started = await post(`/transport-route-amounts/${april}/void`, { reason: 'Too late for this' }, w.office);
    expect([started.status, errorOf(started).code]).toEqual([409, ErrorCode.TRANSPORT_AMOUNT_PERIOD_PAST]);
    const again = await post(`/transport-route-amounts/${august.id}/void`, { reason: 'Twice' }, w.office);
    expect([again.status, errorOf(again).code]).toEqual([409, ErrorCode.STALE_STATUS]);
    expect((await h.audits(w, 'transport_amount.voided')).map((r) => r.reason)).toEqual(['Typed the wrong amount']);
    expect((await h.audits(w, 'transport_amount.set')).length).toBe(3);

    for (const period of ['2026-06', '2026-07', '2027-01']) await month(w, period);
    expect((await charged(w)).map(([, period, amount]) => [period, amount])).toEqual([
      ['2026-06', 2000],
      ['2026-07', 2500],
      ['2027-01', 2500],
    ]);
    const detail = (await h.get(`/transport-routes/${w.route.id}`, w.office).expect(200)).body as { currentAmount: number; nextAmount: unknown };
    expect([detail.currentAmount, detail.nextAmount]).toEqual([2000, { amount: 2500, effectivePeriod: '2026-07' }]);
  });

  it('R328: a concession naming the Transport head applies; a voided month regenerates conceded; the identities hold', async () => {
    const w = await h.world();
    const a = await h.child(w, 'Hamza Tariq');
    await h.assigned(w, a, '2026-04-01');
    const concession = await post(
      '/concessions',
      {
        studentId: a.studentId.toString(),
        academicYearId: w.year.id.toString(),
        kind: 'percentage',
        value: 50,
        feeHeadIds: [w.heads.transport.toString()],
        effectiveFrom: '2026-04',
        reason: 'Sibling bus rate',
      },
      w.office,
      newIdempotencyKey(),
    ).expect(201);
    await post(`/concessions/${(concession.body as { id: string }).id}/approve`, { applyToOpenCharges: false }, w.principal).expect(200);
    await month(w, '2026-04');
    const [april] = await h.transportCharges(w, a.studentId);
    expect([april?.grossAmount, april?.concessionAmount, april?.amount, april?.concessionId === null]).toEqual([2000, 1000, 1000, false]);
    // The tuition is not named by the concession.
    const tuition = await db().charge.findFirstOrThrow({ where: { schoolId: w.school.id, studentId: a.studentId, feeHeadId: w.heads.tuition } });
    expect([tuition.amount, tuition.concessionAmount]).toEqual([3000, 0]);

    // Voided, a catch-up does not bring it back; a run asked to regenerate does, conceded again.
    await post(`/charges/${april?.id}/void`, { reason: 'Charged in error' }, w.principal).expect(200);
    await month(w, '2026-04');
    expect((await h.transportCharges(w, a.studentId)).map((c) => c.status)).toEqual(['voided']);
    await month(w, '2026-04', { regenerateVoided: true });
    const rows = await h.transportCharges(w, a.studentId);
    expect(rows.map((c) => [c.status, c.amount])).toEqual([
      ['voided', 1000],
      ['open', 1000],
    ]);

    // A payment clears the oldest charge first; every charge open exactly while something is owed,
    // and every payment's allocations plus its unallocated amount make its amount (R228 §0.20).
    const payment = (
      await post(
        '/payments',
        {
          academicYearId: w.year.id.toString(),
          payerGuardianId: a.guardianId.toString(),
          studentIds: [a.studentId.toString()],
          amount: 3500,
          method: 'cash',
          receivedOn: clock.state.today,
        },
        w.office,
        newIdempotencyKey(),
      ).expect(201)
    ).body as { id: string };
    const all = await db().charge.findMany({ where: { schoolId: w.school.id, studentId: a.studentId } });
    for (const c of all.filter((x) => x.kind !== 'adjustment')) {
      const owed = c.amount - c.allocatedAmount - c.creditedAmount;
      expect(owed).toBeGreaterThanOrEqual(0);
      if (c.status === 'open' || c.status === 'settled') expect(c.status === 'open').toBe(owed > 0);
    }
    const live = await db().paymentAllocation.aggregate({ where: { schoolId: w.school.id, paymentId: BigInt(payment.id), reversedAt: null }, _sum: { amount: true } });
    const stored = await db().payment.findFirstOrThrow({ where: { schoolId: w.school.id, id: BigInt(payment.id) } });
    expect((live._sum.amount ?? 0) + stored.unallocatedAmount).toBe(3500);
    // The statement: charged − concession − adjustments − paid = outstanding, and it equals Σ owed.
    const statement = (await h.get(`/students/${a.studentId}/fee-statement?academicYearId=${w.year.id}`, w.principal).expect(200)).body as {
      totals: { charged: number; concession: number; adjustments: number; paid: number; outstanding: number };
    };
    const t = statement.totals;
    expect(t.charged - t.concession - t.adjustments - t.paid).toBe(t.outstanding);
    expect(t.outstanding).toBe(all.filter((c) => c.status === 'open').reduce((s, c) => s + c.amount - c.allocatedAmount - c.creditedAmount, 0));
    expect(t.concession).toBe(1000);
  });

  it('A8: a withdrawal ends the live assignment on its date; a later month is not charged', async () => {
    const w = await h.world();
    const a = await h.child(w, 'Hamza Tariq');
    const ride = await h.assigned(w, a, '2026-04-01');
    await month(w, '2026-04');
    clock.state.today = '2026-05-20';
    await post(`/students/${a.studentId}/change-status`, { status: 'withdrawn', effectiveOn: '2026-05-20', reason: 'Family moved city' }, w.office).expect(200);
    const row = await db().transportAssignment.findFirstOrThrow({ where: { schoolId: w.school.id, id: BigInt(ride.id) } });
    expect([row.endsOn, row.endReason, row.endedBy]).toEqual([day('2026-05-20'), 'Student withdrawn', w.office.user.userId]);
    const [audit] = await h.audits(w, 'transport_assignment.ended');
    expect(audit?.metadata).toMatchObject({ via: 'status_change', endsOn: '2026-05-20' });
    await month(w, '2026-05');
    await month(w, '2026-06');
    expect((await charged(w)).map(([, period]) => period)).toEqual(['2026-04', '2026-05']);
  });

  it('R327: a student assigned on the cut-off day is charged; an assignment ended before it began never is', async () => {
    const w = await h.world();
    const a = await h.child(w, 'Hamza Tariq');
    const b = await h.child(w, 'Hira Tariq');
    await h.assigned(w, a, '2026-04-15');
    const future = await h.assigned(w, b, '2026-04-12');
    clock.state.today = '2026-04-11';
    // Ended on the day before it starts: never in force.
    await h.end(w, future.id, '2026-04-11', 'Changed their mind').expect(200);
    const early = await h.end(w, future.id, '2026-04-10');
    expect(early.status).toBe(409);
    await month(w, '2026-04');
    expect(await charged(w)).toEqual([[a.studentId, '2026-04', 2000]]);
    // A later assignment of the same year must start after the earlier one's last day.
    const overlap = await h.assign(w, b, '2026-04-11');
    expect([overlap.status, fieldOf(overlap)?.path]).toEqual([422, 'startsOn']);
    await h.assigned(w, b, '2026-04-13');
  });
});
